import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.nextLine();
        s = s.charAt(0) + s.substring(1, s.length() - 1).replace("dot", ".") + s.charAt(s.length() - 1);
        s = s.charAt(0) + s.substring(1, s.length() - 1).replaceFirst("at", "@") + s.charAt(s.length() - 1);
        System.out.println(s);
        sc.close();
    }
}
